// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListEnvironments Every environment the user can reach, oldest first
	// (GET /environments)
	ListEnvironments(ctx context.Context, request ListEnvironmentsRequestObject) (ListEnvironmentsResponseObject, error)
	// CreateEnvironment Make an environment from a template
	// (POST /environments)
	CreateEnvironment(ctx context.Context, request CreateEnvironmentRequestObject) (CreateEnvironmentResponseObject, error)
	// DeleteEnvironment Delete an environment and its disks
	// (DELETE /environments/{id})
	DeleteEnvironment(ctx context.Context, request DeleteEnvironmentRequestObject) (DeleteEnvironmentResponseObject, error)
	// GetEnvironment One environment
	// (GET /environments/{id})
	GetEnvironment(ctx context.Context, request GetEnvironmentRequestObject) (GetEnvironmentResponseObject, error)
	// ListActivity What has been done to the environment, newest first
	// (GET /environments/{id}/activity)
	ListActivity(ctx context.Context, request ListActivityRequestObject) (ListActivityResponseObject, error)
	// SeeAgent Say the user has looked at an agent's session
	// (POST /environments/{id}/agents/{session}/seen)
	SeeAgent(ctx context.Context, request SeeAgentRequestObject) (SeeAgentResponseObject, error)
	// ResizeDesktop Sets the size of the environment's desktop
	// (POST /environments/{id}/desktop/size)
	ResizeDesktop(ctx context.Context, request ResizeDesktopRequestObject) (ResizeDesktopResponseObject, error)
	// ChangeEnvironmentImage Upgrade the environment's image, roll it back, or keep the upgrade
	// (POST /environments/{id}/image/{change})
	ChangeEnvironmentImage(ctx context.Context, request ChangeEnvironmentImageRequestObject) (ChangeEnvironmentImageResponseObject, error)
	// GetEnvironmentLog Part of one of the environment's logs, from its worker
	// (GET /environments/{id}/logs/{log})
	GetEnvironmentLog(ctx context.Context, request GetEnvironmentLogRequestObject) (GetEnvironmentLogResponseObject, error)
	// ListEnvironmentPacks The packs of shared files the environment has, and the copy of each it uses
	// (GET /environments/{id}/packs)
	ListEnvironmentPacks(ctx context.Context, request ListEnvironmentPacksRequestObject) (ListEnvironmentPacksResponseObject, error)
	// ChooseEnvironmentCopy Choose which copy of a pack the environment uses
	// (PUT /environments/{id}/packs/{pack})
	ChooseEnvironmentCopy(ctx context.Context, request ChooseEnvironmentCopyRequestObject) (ChooseEnvironmentCopyResponseObject, error)
	// SetEnvironmentPorts Say who may reach the environment's own web servers
	// (PUT /environments/{id}/ports)
	SetEnvironmentPorts(ctx context.Context, request SetEnvironmentPortsRequestObject) (SetEnvironmentPortsResponseObject, error)
	// ListProcesses The processes running in the environment
	// (GET /environments/{id}/processes)
	ListProcesses(ctx context.Context, request ListProcessesRequestObject) (ListProcessesResponseObject, error)
	// SignalProcess Stops a process, asking it (TERM) or forcing it (KILL)
	// (POST /environments/{id}/processes/{pid}/signal)
	SignalProcess(ctx context.Context, request SignalProcessRequestObject) (SignalProcessResponseObject, error)
	// ResetEnvironment Give a stopped environment its template's current settings
	// (POST /environments/{id}/reset)
	ResetEnvironment(ctx context.Context, request ResetEnvironmentRequestObject) (ResetEnvironmentResponseObject, error)
	// UpdateEnvironmentSettings Change the environment's machine
	// (PUT /environments/{id}/settings)
	UpdateEnvironmentSettings(ctx context.Context, request UpdateEnvironmentSettingsRequestObject) (UpdateEnvironmentSettingsResponseObject, error)
	// StartEnvironment Ask for an environment to run
	// (POST /environments/{id}/start)
	StartEnvironment(ctx context.Context, request StartEnvironmentRequestObject) (StartEnvironmentResponseObject, error)
	// StopEnvironment Ask for an environment to stop, keeping its disks
	// (POST /environments/{id}/stop)
	StopEnvironment(ctx context.Context, request StopEnvironmentRequestObject) (StopEnvironmentResponseObject, error)
	// SuspendEnvironment Ask for an environment to suspend, keeping its memory on disk
	// (POST /environments/{id}/suspend)
	SuspendEnvironment(ctx context.Context, request SuspendEnvironmentRequestObject) (SuspendEnvironmentResponseObject, error)
	// EndTask Mark an environment's task done, leaving it none
	// (DELETE /environments/{id}/task)
	EndTask(ctx context.Context, request EndTaskRequestObject) (EndTaskResponseObject, error)
	// SetTask Set what an environment is for, ending its task before
	// (PUT /environments/{id}/task)
	SetTask(ctx context.Context, request SetTaskRequestObject) (SetTaskResponseObject, error)
	// ListTasks An environment's tasks, newest first, its task among them
	// (GET /environments/{id}/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// ListTerminals The environment's terminal sessions
	// (GET /environments/{id}/terminals)
	ListTerminals(ctx context.Context, request ListTerminalsRequestObject) (ListTerminalsResponseObject, error)
	// CloseTerminal End a terminal session, ending what runs in it
	// (DELETE /environments/{id}/terminals/{session})
	CloseTerminal(ctx context.Context, request CloseTerminalRequestObject) (CloseTerminalResponseObject, error)
	// StreamEvents Changes to the environments the user can reach, as they happen
	// (GET /events)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// GetMe The signed-in user, and how to reach their environments over SSH
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListLoginKeys The public keys that sign the user in over SSH
	// (GET /me/login-keys)
	ListLoginKeys(ctx context.Context, request ListLoginKeysRequestObject) (ListLoginKeysResponseObject, error)
	// AddLoginKey Add a public key that signs the user in over SSH
	// (POST /me/login-keys)
	AddLoginKey(ctx context.Context, request AddLoginKeyRequestObject) (AddLoginKeyResponseObject, error)
	// DeleteLoginKey Remove a public key that signs the user in over SSH
	// (DELETE /me/login-keys/{id})
	DeleteLoginKey(ctx context.Context, request DeleteLoginKeyRequestObject) (DeleteLoginKeyResponseObject, error)
	// ListSSHKeys The SSH keys the server signs with for the user. Their private halves never leave the server.
	// (GET /me/ssh-keys)
	ListSSHKeys(ctx context.Context, request ListSSHKeysRequestObject) (ListSSHKeysResponseObject, error)
	// GenerateSSHKey Make a new SSH key for the user, kept on the server
	// (POST /me/ssh-keys)
	GenerateSSHKey(ctx context.Context, request GenerateSSHKeyRequestObject) (GenerateSSHKeyResponseObject, error)
	// DeleteSSHKey Remove one of the user's SSH keys
	// (DELETE /me/ssh-keys/{id})
	DeleteSSHKey(ctx context.Context, request DeleteSSHKeyRequestObject) (DeleteSSHKeyResponseObject, error)
	// ListTokens The user's access tokens, the one this request came with marked
	// (GET /me/tokens)
	ListTokens(ctx context.Context, request ListTokensRequestObject) (ListTokensResponseObject, error)
	// RevokeToken End one of the user's access tokens
	// (DELETE /me/tokens/{id})
	RevokeToken(ctx context.Context, request RevokeTokenRequestObject) (RevokeTokenResponseObject, error)
	// StartSignIn Begin signing an app in through the browser: the app shows the code, opens verification_path on this server, where the person signs in and approves it, and collects its token from /sign-in/token.
	// (POST /sign-in)
	StartSignIn(ctx context.Context, request StartSignInRequestObject) (StartSignInResponseObject, error)
	// FinishSignIn Collect the access token an approved grant makes, once. 202 while it waits to be approved: ask again after the grant's interval.
	// (POST /sign-in/token)
	FinishSignIn(ctx context.Context, request FinishSignInRequestObject) (FinishSignInResponseObject, error)
	// ListTemplates The templates the user may make an environment from
	// (GET /templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// GetVersion Which versions of this API the server serves, and its build
	// (GET /version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
	// ListWorkerSizes How big an environment may be
	// (GET /worker-sizes)
	ListWorkerSizes(ctx context.Context, request ListWorkerSizesRequestObject) (ListWorkerSizesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

